// Package version defines the semantic version of the operator generator.
package version

import "strings"

// Current is the semantic version of the generator. tools/opgen/versions.yaml holds it for every
// generated kind.
const Current = "v0.1.0-beta.2"

// Tool is the name of the generator in the header of every generated file.
const Tool = "coralogix-operator-codegen"

// VersionsFile is the generated file that holds the generator version of each kind, relative to
// the operator root. The generated files do not hold the version, so a new version changes only
// this file and the files whose output changes.
const VersionsFile = "tools/opgen/versions.yaml"

// GoHeaderLine is the exact first line of every generated Go file.
const GoHeaderLine = "// Code generated by " + Tool + ". DO NOT EDIT."

// GoHeader is the exact header of every generated Go file: the first line, and a fixed line that
// tells where the version is.
const GoHeader = GoHeaderLine + "\n// The generator version is in " + VersionsFile + "."

// YAMLHeaderLine is the exact first line of every generated YAML file.
const YAMLHeaderLine = "# Code generated by " + Tool + ". DO NOT EDIT."

// YAMLHeader is the exact header of every generated YAML file.
const YAMLHeader = YAMLHeaderLine + "\n# The generator version is in " + VersionsFile + "."

// Owned reports whether line is the first line of a file that a version of the generator wrote.
// The generator overwrites or removes only such a file. Older versions wrote the version into
// the line (Code generated by coralogix-operator-codegen v0.1.0-beta.3. DO NOT EDIT.), so such a
// line is the generator's too.
func Owned(line string) bool {
	if line == GoHeaderLine || line == YAMLHeaderLine {
		return true
	}
	for _, prefix := range []string{"// ", "# "} {
		rest, ok := strings.CutPrefix(line, prefix+"Code generated by "+Tool+" v")
		if !ok {
			continue
		}
		semver, ok := strings.CutSuffix(rest, ". DO NOT EDIT.")
		return ok && semver != "" && !strings.ContainsAny(semver, " \t")
	}
	return false
}
